<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Usuários · MetaFit Admin</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="https://unpkg.com/tabulator-tables@6.3.1/dist/css/tabulator_bootstrap5.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css" rel="stylesheet"><link href="assets/css/style.css?v=0.1.3" rel="stylesheet"><style>.tabulator-row .tabulator-cell{display:inline-flex}#users-type-filter{width:190px;min-height:34px;border-color:#dde5ee;font-size:.8rem}</style></head>
<body class="app-page"><aside class="sidebar"><a class="brand" href="/users"><span class="brand-mark"><i class="bi bi-activity"></i></span>meta<span>fit</span></a><nav class="sidebar-nav"><span class="nav-caption">GERAL</span><a class="active" href="/users"><i class="bi bi-people"></i> Usuários</a></nav><div class="sidebar-bottom"><div class="current-user"><span class="avatar" id="user-initials"></span><div><strong id="user-name"></strong><small>Administrador</small></div></div><button id="logout-button" class="btn btn-link"><i class="bi bi-box-arrow-left"></i> Sair</button></div></aside>
<main class="main-content"><header class="page-header"><div><p class="eyebrow">GESTÃO DE PESSOAS</p><h1>Usuários</h1><p class="text-muted mb-0">Visualize e cadastre pessoas na plataforma.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#user-modal"><i class="bi bi-person-plus me-2"></i>Novo usuário</button></header><section class="content-card"><div class="table-toolbar"><div class="search-box"><i class="bi bi-search"></i><input id="users-search" type="search" placeholder="Buscar por nome, e-mail ou WhatsApp"></div><span id="users-count" class="text-muted"></span></div><div id="users-table"></div></section></main>
<div class="modal fade" id="user-modal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="user-form" novalidate><div class="modal-header"><div><p class="eyebrow mb-1">NOVO CADASTRO</p><h5 class="modal-title">Adicionar usuário</h5></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label" for="user-nome">Nome completo</label><input class="form-control" id="user-nome" required></div><div class="col-md-7"><label class="form-label" for="user-email">E-mail</label><input type="email" class="form-control" id="user-email" required></div><div class="col-md-5"><label class="form-label" for="user-whatsapp">WhatsApp</label><input class="form-control" id="user-whatsapp" required placeholder="(00) 00000-0000"></div><div class="col-md-6"><label class="form-label" for="user-senha">Senha temporária</label><input type="password" class="form-control" id="user-senha" minlength="8" required><small class="form-text">Mínimo de 8 caracteres.</small></div><div class="col-md-6"><label class="form-label" for="user-tipo">Perfil</label><select class="form-select fluid-select" id="user-tipo"><option value="usuario">Usuário</option><option value="admin">Administrador</option></select></div></div><div id="user-alert" class="alert alert-danger d-none mt-4 mb-0"></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button id="user-submit" type="submit" class="btn btn-primary">Cadastrar usuário</button></div></form></div></div></div>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://unpkg.com/tabulator-tables@6.3.1/dist/js/tabulator.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script src="assets/js/config.js?v=0.1.1"></script><script src="assets/js/api.js?v=0.1.1"></script><script src="assets/js/users.js?v=0.1.2"></script></body></html>
